import React, { useState } from 'react';
import axios from 'axios';

function AddBook({ onAdd, showToast }) {
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      await axios.post('http://localhost:5000/api/books', 
        { title, author },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setTitle('');
      setAuthor('');
      if (showToast) showToast('Book added successfully!');
      if (onAdd) onAdd();
    } catch (err) {
      if (showToast) showToast(err.response?.data?.message || 'Failed to add book');
    }
    setLoading(false);
  };

  return (
    <div className="bg-gray-50 rounded-lg p-6 mb-6 border border-gray-200">
      <div className="text-lg font-semibold mb-4 text-gray-800">Add New Book</div>
      <form onSubmit={handleSubmit} className="w-full">
        <input
          className="w-full p-3 mb-3 border border-gray-300 rounded-lg text-base bg-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          type="text"
          placeholder="Title"
          value={title}
          onChange={e => setTitle(e.target.value)}
          required
        />
        <input
          className="w-full p-3 mb-4 border border-gray-300 rounded-lg text-base bg-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          type="text"
          placeholder="Author"
          value={author}
          onChange={e => setAuthor(e.target.value)}
          required
        />
        <button 
          className="px-6 py-2 bg-gradient-button text-white border-none rounded-lg font-semibold cursor-pointer hover:bg-gradient-button-hover transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
          type="submit" 
          disabled={loading}
        >
          {loading ? 'Adding...' : 'Add Book'}
        </button>
      </form>
    </div>
  );
}

export default AddBook;
